const config = { timeout: 100 };
let counter = 0;

async function fetchNumber() {
  return new Promise((resolve) => {
    setTimeout(() => resolve(42), config.timeout);
  });
}

const proto = {
  greet() {
    return `Hello, the number is ${this.number}`;
  }
};

const child = Object.create(proto);
child.number = null;

(async () => {
  const result = await fetchNumber();
  child.number = result;
  counter += result;
  console.log(child.greet());
  console.log('Counter is', counter);
})();

